<?php
if(!isset($periodData,$periodLabel,$periodKey))return;
$periodResult=$periodData['result'];$periodVisible=$periodData['visible'];
?>
<section class="student-gradebook-period" data-grade-period="<?= synk_student_h($periodKey) ?>" aria-label="<?= synk_student_h($periodLabel) ?> grading breakdown"><header><h3><i class="bx <?= $periodKey==='midterm'?'bx-calendar-event':'bx-calendar-check' ?>" aria-hidden="true"></i><?= synk_student_h($periodLabel) ?></h3><?php if($periodVisible): ?><strong><?= synk_student_gradebook_number_lms($periodResult['percent'],true) ?></strong><?php else: ?><span class="student-gradebook-hidden">Not released</span><?php endif; ?></header>
<?php if(!$periodVisible): ?><p class="student-gradebook-unavailable">Your instructor has not released your <?= synk_student_h($periodLabel) ?> grade and score breakdown yet.</p>
<?php elseif(!$periodResult['complete']): ?><p class="student-gradebook-unavailable">Your instructor has not yet completed this period’s grading setup.</p><?php else: ?>
<div class="student-gradebook-component-scroll" tabindex="0" role="region" aria-label="<?= synk_student_h($periodLabel) ?> components"><table class="student-gradebook-components"><caption class="visually-hidden"><?= synk_student_h($periodLabel) ?> component calculation</caption><thead><tr><th scope="col">Component</th><th scope="col">Weight</th><th scope="col">Score / max</th><th scope="col">Contribution</th></tr></thead><tbody><?php foreach($periodResult['components'] as $component): ?><tr><th scope="row"><?= synk_student_h($component['name']) ?><small><?= (int)$component['item_count'] ?> item<?= $component['item_count']===1?'':'s' ?><?= $component['pending_count']>0?' · '.(int)$component['pending_count'].' unrecorded':'' ?></small></th><td><?= synk_student_gradebook_number_lms($component['weight'],true) ?></td><td><?= synk_student_gradebook_number_lms($component['earned']) ?> / <?= synk_student_gradebook_number_lms($component['possible']) ?></td><td><?= synk_student_gradebook_number_lms($component['contribution'],true) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th scope="row" colspan="3">Period grade</th><td><?= synk_student_gradebook_number_lms($periodResult['percent'],true) ?></td></tr></tfoot></table></div>
<p class="student-gradebook-record-count"><?= (int)$periodResult['graded_count'] ?> of <?= (int)$periodResult['item_count'] ?> entries have a recorded or automatically checked score.</p>
<?php if($periodData['entries']): ?><details class="student-gradebook-entries"><summary>View recorded work <span><?= count($periodData['entries']) ?> <?= count($periodData['entries'])===1?'entry':'entries' ?></span><i class="bx bx-chevron-down" aria-hidden="true"></i></summary><div class="student-gradebook-component-scroll" tabindex="0" role="region" aria-label="<?= synk_student_h($periodLabel) ?> recorded work"><table class="student-gradebook-work"><caption class="visually-hidden"><?= synk_student_h($periodLabel) ?> score entries</caption><thead><tr><th scope="col">Work / component</th><th scope="col">Score / max</th><th scope="col">Source</th></tr></thead><tbody><?php foreach($periodData['entries'] as $entry): ?><tr><th scope="row"><?= synk_student_h($entry['title']) ?><small><?= synk_student_h($entry['component']) ?><?= $entry['date']!==null?' · '.synk_student_h((new DateTimeImmutable($entry['date']))->format('M j, Y')):'' ?></small></th><td><?= $entry['points']===null?'Unrecorded':synk_student_gradebook_number_lms($entry['points']) ?> / <?= synk_student_gradebook_number_lms($entry['maximum']) ?></td><td><?= $entry['source']==='manual'?'Manual':($entry['source']==='lms'?'LMS':'Unrecorded') ?><small><?= synk_student_h($entry['explanation']) ?></small></td></tr><?php endforeach; ?></tbody></table></div></details>
<?php else: ?><p class="student-gradebook-unavailable">No entries have been added to this grading period yet.</p><?php endif; ?>
<?php endif; ?></section>
